import React, { Component } from 'react'
import { Grid } from "@material-ui/core";
import ToggleButton from '@mui/material/ToggleButton';
import ToggleButtonGroup from '@mui/material/ToggleButtonGroup';
import { styled } from '@mui/material/styles';

const CustomToggleButton = styled(ToggleButton)(({ theme }) => ({
  color: 'black',
  border: '1px solid black', // Add border to the button
  '&.Mui-selected': {
    backgroundColor: '#3f51b5', // Darker blue color
    color: 'white',
    border: '1px solid black', // Add border to the selected button
  },
  '&:not(.Mui-selected)': {
    backgroundColor: 'grey',
    border: '1px solid black', // Add border to the non-selected button
  },
}));

class MappingsPane extends Component {
  constructor(props) {
    super(props)
    
    // 임베딩 옵션 첫 번째 값 추출 시도
    let initialEmbedding = '';
    if (props.algorithm_options && props.algorithm_options.length > 0) {
      const embeddingOptions = [...new Set(
        props.algorithm_options.map(opt => {
          const parts = opt.split('_');
          return parts.slice(0, -1).join('_');
        }).filter(Boolean)
      )].filter(opt => opt !== 'grid');
      initialEmbedding = embeddingOptions.length > 0 ? embeddingOptions[0] : '';
    }

    this.state = {
      selectedEmbedding: initialEmbedding,
      gird: '',
    }
    
    this.handleSelectEmbedding = this.handleSelectEmbedding.bind(this);
    this.handleSelectDataset = this.handleSelectDataset.bind(this);
    this.handleSelectProjection = this.handleSelectProjection.bind(this);
  }

  componentDidMount() {
    // 초기 임베딩이 설정되었다면 프로젝션 초기화
    if (this.state.selectedEmbedding && this.props.algorithm_options) {
      this.props.selectProjection('grid');
      const labelOption = this.props.algorithm_options.find(opt => opt.startsWith('grid'));
      this.setState({ gird: labelOption });
      
      if (labelOption) {
        this.props.selectAlgorithm(labelOption);
      } else {
        const embeddingName = this.state.selectedEmbedding;
        const selectedOption = this.props.algorithm_options.find(
          opt => opt.startsWith(embeddingName + '_')
        );
        this.props.embeddingName = embeddingName;
        if (selectedOption) {
          this.props.selectAlgorithm(selectedOption);
        } else {
          this.props.selectAlgorithm('grid');
        }
      }
    }
  }

  handleSelectEmbedding(e) {
    let v = e.target.value;
    
    // 임베딩 선택 후 프로젝션을 grid로 설정
    this.setState({ selectedEmbedding: v });
    
    // 임베딩 변경 시 해당 임베딩의 기본 데이터 로드 (label_label)
    // 안전하게 algorithm_options 체크
    const selectedOption = this.props.algorithm_options.find(opt => opt.startsWith(v + '_' + this.props.selectedProjection));
    if (selectedOption) { 
      this.props.selectAlgorithm(selectedOption);
    } else {
      this.props.selectAlgorithm(v);
    }
  }

  handleSelectDataset(e) {
    let v = e.target.value;
    this.props.selectDataset(v);
  }

  handleSelectProjection(event, newProjection) {
    if (newProjection !== null) {
      // 현재 선택된 임베딩 이름 가져오기
      const currentEmbedding = this.state.selectedEmbedding;
      console.log(currentEmbedding);
      // 임베딩과 프로젝션 조합
      const combinedOption = this.props.algorithm_options.find(
        opt => opt.startsWith(currentEmbedding + '_' + newProjection)
      );
      if (combinedOption) {
        this.props.selectAlgorithm(combinedOption);
      }
      else {
        this.props.selectAlgorithm(this.state.gird);
      }
      
      // 프로젝션 상태 업데이트
      this.props.selectProjection(newProjection);
    }
  }

  render() {
    let {
      algorithm_options,
      dataset_options,
      selectedDataset,
      datasetInfo,
      selectedProjection,
    } = this.props;
    
    // 임베딩 옵션 추출 (중복 제거)
    const embeddingOptions=[...new Set(algorithm_options?algorithm_options.map(opt=>{const parts=opt.split('_');return parts.slice(0,-1).join('_')}).filter(Boolean):[])]

    return (
      <Grid container spacing={1}>
          <Grid item xs={4}>
            Dataset:
          </Grid>
          <Grid item xs={8}>
            <select className="full-width"
              onChange={this.handleSelectDataset}
              value={selectedDataset}
            >
              {dataset_options.map((option, index) => (
              <option key={option} value={option}>
                  {option}
              </option>
              ))}
            </select>
          </Grid>

          <Grid item xs={4}>
            Embedding:
          </Grid>
          <Grid item xs={8}>
            <select className="full-width"
              onChange={this.handleSelectEmbedding}
              value={this.state.selectedEmbedding}
            >
              {embeddingOptions.map((option, index) => (
              <option key={option} value={option}>
                  {option}
              </option>
              ))}
            </select>
          </Grid>

          <Grid item xs={4}>
            Projection:
          </Grid>
          <Grid item xs={8}>
            <ToggleButtonGroup
              size="small"
              fullWidth
              exclusive
              value={selectedProjection || 'grid'}
              onChange={this.handleSelectProjection}
              aria-label="projection type"
            >
              <CustomToggleButton value="grid">grid</CustomToggleButton>
              <CustomToggleButton value="pca">pca</CustomToggleButton>
              <CustomToggleButton value="tsne">tsne</CustomToggleButton>
              <CustomToggleButton value="umap">umap</CustomToggleButton>
            </ToggleButtonGroup>
          </Grid>
          <Grid item xs={12}>
          <p className="info">{datasetInfo}</p>
          </Grid>
      </Grid>
    )
  }
}

export default React.memo(MappingsPane)