import React from "react";
import {
  BrowserRouter, Routes, Route
} from "react-router-dom";

// Area components
import './App.css'
import WithRouter from './Data'

export default function App() {
  
  return (
    <BrowserRouter basename="/ladybirdmnist-explorer">
      <Routes>
        <Route exact path="/" element={<WithRouter/>} />
        <Route exact path="/ladybirdmnist-explorer" element={<WithRouter/>}/> 
      </Routes>
    </BrowserRouter>
  );

}