import React, { Component } from 'react'
import { Grid, Button } from "@material-ui/core";
import ToggleButton from '@mui/material/ToggleButton';
import { styled } from '@mui/material/styles';

// 동적 스타일을 위해 함수형 스타일 사용
const NumberToggleButton = styled(ToggleButton)(({ theme, color, selected }) => ({
  minWidth: '30px',
  margin: '2px',
  backgroundColor: selected ? color : 'grey',
  color: 'white',
  '&.Mui-selected': {
    backgroundColor: color,
    color: 'white',
    border: '1px solid black', // Add border to the selected button
    '&:hover': {
      backgroundColor: color,
      opacity: 0.9,
    },
  },
  '&:hover': {
    backgroundColor: selected ? color : '#666',
    opacity: 0.9,
  },
}));

class LabelPane extends Component {
  constructor(props) {
    super(props);
    
    // Sliders와 유사하게 초기화
    this.labelCounts = new Array(10).fill(0);
    this.filtered = {};
    
    // metadata에서 라벨 정보 추출
    const { metadata } = this.props;
    if (metadata) {
      for (let element in metadata) {
        if (metadata[element].hasOwnProperty('label')) {
          const labelIndex = parseInt(metadata[element].label);
          if (labelIndex >= 0 && labelIndex < 10) {
            this.labelCounts[labelIndex]++;
          }
        }
      }
    }
    
    this.state = {
      selectedLabels: new Array(10).fill(true),
      clusterColorsEnabled: true,
      selectedCluster: "disabled",
      labelsEnabled: true  // 라벨 표시 여부 상태 추가
    };
    
    this.toggleLabel = this.toggleLabel.bind(this);
    this.resetLabels = this.resetLabels.bind(this);
    this.selectAllLabels = this.selectAllLabels.bind(this);
    this.deselectAllLabels = this.deselectAllLabels.bind(this);
    this.toggleClusterColors = this.toggleClusterColors.bind(this);
    this.handleClusterChange = this.handleClusterChange.bind(this);
    this.toggleLabelsVisibility = this.toggleLabelsVisibility.bind(this);
    this.toggleBoth = this.toggleBoth.bind(this);
  }

  toggleLabel(labelIndex) {
    const newSelectedLabels = [...this.state.selectedLabels];
    
    // 현재 모든 라벨이 선택된 상태에서 하나의 라벨을 클릭하면 해당 라벨만 선택
    if (newSelectedLabels.every(label => label === true)) {
      newSelectedLabels.fill(false);
      newSelectedLabels[labelIndex] = true;
    } else {
      // 이미 일부만 선택된 상태라면 토글 동작
      newSelectedLabels[labelIndex] = !newSelectedLabels[labelIndex];
      
      // 모든 라벨이 해제되는 것을 방지 (최소 하나는 선택되어야 함)
      if (newSelectedLabels.every(label => label === false)) {
        newSelectedLabels[labelIndex] = true;
      }
    }
    
    this.setState({ selectedLabels: newSelectedLabels }, () => {
      this.applyFilter();
    });
  }

  resetLabels() {
    this.setState({ selectedLabels: new Array(10).fill(true) }, () => {
      this.applyFilter();
    });
  }
  
  selectAllLabels() {
    this.setState({ selectedLabels: new Array(10).fill(true) }, () => {
      this.applyFilter();
    });
  }
  
  deselectAllLabels() {
    // 모든 라벨을 해제하려고 할 때 첫 번째 라벨은 선택 상태로 유지
    const newSelectedLabels = new Array(10).fill(false);
    newSelectedLabels[0] = true;
    this.setState({ selectedLabels: newSelectedLabels }, () => {
      this.applyFilter();
    });
  }

  applyFilter() {
    const { metadata, settings } = this.props;
    const { selectedLabels } = this.state;
    
    // 모든 라벨이 선택된 경우 필터를 적용하지 않음
    if (selectedLabels.every(label => label === true)) {
      // 필터 해제 (모든 데이터 표시)
      const noFilterArr = new Float32Array(settings.total).fill(0);
      this.props.calculateProjection(noFilterArr, "filter", true);
      return;
    }
    
    // 선택된 라벨에 속하는 데이터는 그대로 표시하고, 선택되지 않은 라벨의 데이터는 흐리게 표시
    const filteredArr = new Float32Array(settings.total).fill(1); 
    
    for (let element in metadata) {
      if (metadata[element].hasOwnProperty('label')) {
        const label = parseInt(metadata[element].label);
        if (label >= 0 && label < 10 && selectedLabels[label]) {
          // 선택된 라벨에 해당하는 데이터는 완전히 표시
          filteredArr[element] = 0;
        }
      }
    }
    
    this.props.calculateProjection(filteredArr, "filter", true);
    this.props.handleChangeGrey(0);
  }

  toggleClusterColors() {
    this.setState(prevState => ({
      clusterColorsEnabled: !prevState.clusterColorsEnabled
    }));
  }
  
  handleClusterChange(event) {
    this.setState({
      selectedCluster: event.target.value
    });
    if (this.props.handleChangeCluster) {
      this.props.handleChangeCluster(event);
    }
  }

  toggleLabelsVisibility() {
    // 라벨 상태를 먼저 업데이트
    this.setState(prevState => ({
      labelsEnabled: !prevState.labelsEnabled
    }), () => {
      // 라벨 표시 여부에 따라 클러스터 설정 변경
      const clusterValue = this.state.labelsEnabled ? "label" : "disabled";
      
      // 직접 props의 handleChangeCluster 함수 호출
      if (this.props.handleChangeCluster) {
        const syntheticEvent = {
          target: {
            value: clusterValue
          }
        };
        this.props.handleChangeCluster(syntheticEvent);
      }
    });
  }

  toggleBoth() {
    // 두 상태를 동시에 토글
    this.setState(prevState => ({
      labelsEnabled: !prevState.labelsEnabled,
      clusterColorsEnabled: !prevState.clusterColorsEnabled
    }), () => {
      // 라벨 표시 여부에 따라 클러스터 설정 변경
      const clusterValue = this.state.labelsEnabled ? "label" : "disabled";
      
      // 직접 props의 handleChangeCluster 함수 호출
      if (this.props.handleChangeCluster) {
        const syntheticEvent = {
          target: {
            value: clusterValue
          }
        };
        this.props.handleChangeCluster(syntheticEvent);
      }
    });
  }

  render() {
    const { selectedLabels, clusterColorsEnabled, selectedCluster, labelsEnabled } = this.state;
    const { settings } = this.props;
    const clusterColors = settings['clusters']['clusterColors'];
    const clusters = settings['clusters'];
    
    const rgbArrayToColor = (rgbArray) => {
      if (!clusterColorsEnabled || !rgbArray || rgbArray.length !== 3) return 'grey';
      const r = Math.round(rgbArray[0] * 255);
      const g = Math.round(rgbArray[1] * 255);
      const b = Math.round(rgbArray[2] * 255);
      return `rgb(${r}, ${g}, ${b})`;
    };
    
    return (
      <Grid container spacing={2}>
        <Grid item xs={12}>
          <div style={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'center' }}>
            {[...Array(5)].map((_, index) => (
              <NumberToggleButton 
                key={index} 
                selected={selectedLabels[index]}
                onClick={() => this.toggleLabel(index)}
                value={index.toString()}
                color={rgbArrayToColor(clusterColors[index])}
              >
                {index}
              </NumberToggleButton>
            ))}
          </div>
          <div style={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'center', marginTop: '4px' }}>
            {[...Array(5)].map((_, index) => {
              const buttonIndex = index + 5;
              return (
                <NumberToggleButton 
                  key={buttonIndex} 
                  selected={selectedLabels[buttonIndex]}
                  onClick={() => this.toggleLabel(buttonIndex)}
                  value={buttonIndex.toString()}
                  color={rgbArrayToColor(clusterColors[buttonIndex])}
                >
                  {buttonIndex}
                </NumberToggleButton>
              );
            })}
          </div>
        </Grid>
        
        <Grid item xs={12}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: '8px' }}>
            <Button 
              variant="outlined" 
              size="small" 
              color="primary"
              onClick={this.toggleBoth}
              style={{ marginRight: '8px', minWidth: '150px' }}
            >
              {labelsEnabled ? "Disable Label/Color" : "Enable Label/Color"}
            </Button>
            <Button 
              variant="contained" 
              color="primary" 
              onClick={this.selectAllLabels}
              style={{ marginRight: '8px' }}
            >
              Select All
            </Button>
          </div>
        </Grid>
      </Grid>
    );
  }
}

export default React.memo(LabelPane)